  .type Reset_Handler, %function
Reset_Handler:
  ldr   sp, =_estack
  /* copy .data initial values from flash to RAM */
  ldr   r0, =_sdata
  ldr   r1, =_edata
  ldr   r2, =_sidata
1:
  cmp   r0, r1
  itt   lo
  ldrlo r3, [r2], #4
  strlo r3, [r0], #4
  blo   1b
  /* zero .bss */
  ldr   r0, =_sbss
  ldr   r1, =_ebss
  movs  r3, #0
2:
  cmp   r0, r1
  itt   lo
  strlo r3, [r0], #4
  blo   2b

  bl    SystemInit
  bl    __libc_init_array
  bl    main
  bx    lr
  .size Reset_Handler, .-Reset_Handler

